/* RangeLab preflop models. All stack sizes and payoffs are in big blinds. */
(() => {
  'use strict';

  // Lower triangle of 169 x 169 heads-up showdown equities. Each uint16 is a
  // split-pot mean from 12,288 seeded uniform compatible deals and five-card runouts.
  const equitySample = '';

  const tieSample = '';
  const ranks = 'AKQJT98765432'.split('');
  const positions = ['UTG', 'HJ', 'CO', 'BTN', 'SB', 'BB'];
  const DEFAULT_CONFIG = {model: 'cash', hero: 'BB', villain: 'BTN', stack: 100, openSize: 2.5};
  const n = ranks.length ** 2;
  const classes = [];
  const matchups = new Float32Array(n * n);
  const equity = new Float64Array(n * n);
  const ties = new Float64Array(n * n);
  const sample = atob(equitySample);
  const tieBytes = atob(tieSample);

  for (let row = 0; row < 13; row++) {
    for (let col = 0; col < 13; col++) {
      const high = Math.min(row, col);
      const low = Math.max(row, col);
      const pair = row === col;
      const suited = col > row;
      const name = ranks[high] + ranks[low] + (pair ? '' : suited ? 's' : 'o');
      classes.push({name, row, col, high, low, pair, suited, deals: []});
    }
  }
  for (let first = 0; first < 52; first++) {
    for (let second = first + 1; second < 52; second++) {
      const hi = second >> 2;
      const lo = first >> 2;
      const index = (first % 4 === second % 4) ? (12 - hi) * 13 + 12 - lo : (12 - lo) * 13 + 12 - hi;
      classes[index].deals.push([first, second]);
    }
  }
  let sampleIndex = 0, tieIndex = 0;
  for (let i = 0; i < n; i++) {
    const [a, b] = classes[i].deals[0];
    for (let j = 0; j < n; j++) {
      const legal = classes[j].deals.filter(([c, d]) => c !== a && c !== b && d !== a && d !== b);
      matchups[i * n + j] = legal.length / 1225;
      if (j < i) {
        const value = sample.charCodeAt(sampleIndex++) | (sample.charCodeAt(sampleIndex++) << 8);
        equity[i * n + j] = value / 65535;
        equity[j * n + i] = 1 - value / 65535;
      } else if (j === i) {
        equity[i * n + j] = 0.5;
      }
      if (j <= i) {
        const tied = tieBytes.charCodeAt(tieIndex++) | (tieBytes.charCodeAt(tieIndex++) << 8);
        ties[i * n + j] = ties[j * n + i] = tied / 65535;
      }
    }
    classes[i].combos = classes[i].deals.length;
  }

  function clamp(value, low, high) {
    return Math.min(high, Math.max(low, value));
  }

  function numeric(value, fallback, low, high) {
    return Number.isFinite(Number(value)) ? clamp(Number(value), low, high) : fallback;
  }

  function normalize(input = {}) {
    const model = input.model === 'pushfold' ? 'pushfold' : 'cash';
    const hero = model === 'pushfold' ? (input.hero === 'SB' ? 'SB' : 'BB')
      : positions.includes(input.hero) ? input.hero : 'BB';
    const villain = model === 'pushfold' ? (hero === 'SB' ? 'BB' : 'SB')
      : input.villain === 'none' ? 'none' : positions.includes(input.villain) ? input.villain : 'BTN';
    const stack = numeric(input.stack ?? (model === 'cash' ? 100 : 10), 100, model === 'cash' ? 5 : 1, 1000);
    const openSize = numeric(input.openSize ?? 2.5, 2.5, 2, stack);
    return {model, hero, villain, stack, openSize, locks: input.locks || {}};
  }

  function rangeEquity(i, weights) {
    let reached = 0;
    let wins = 0;
    for (let j = 0; j < n; j++) {
      const w = matchups[i * n + j] * weights[j];
      reached += w;
      wins += w * equity[i * n + j];
    }
    return reached > 0 ? wins / reached : 0.5;
  }

  const uniform = new Float32Array(n).fill(1);
  const randomEquity = classes.map((_, i) => rangeEquity(i, uniform));
  // Order preflop opens using raw equity and postflop playability. Percentiles
  // account for the six pair, four suited and twelve offsuit combinations.
  const ordered = classes.map((hand, i) => {
    const gap = hand.low - hand.high;
    const suitBonus = hand.suited ? .047 + .004 * Math.max(0, 5 - gap) : 0;
    const pairBonus = hand.pair ? .045 + hand.high * .0015 : 0;
    return {i, score: randomEquity[i] + suitBonus + pairBonus};
  }).sort((a, b) => b.score - a.score);
  const percentile = new Float64Array(n);
  let combinations = 0;
  for (const {i} of ordered) {
    percentile[i] = (combinations + classes[i].combos / 2) / 1326;
    combinations += classes[i].combos;
  }

  const openWidth = {UTG: .169, HJ: .214, CO: .298, BTN: .461, SB: .433, BB: .461};
  function sizeAdjustedWidth(position, size) {
    return Math.max(.033, openWidth[position] / (1 + .09 * (size - 2.5)));
  }
  function openWeight(position, i, size = 2.5) {
    return clamp(.5 + (sizeAdjustedWidth(position, size) - percentile[i]) / .043, 0, 1);
  }

  function roundEV(value) {
    return Math.round(value * 1000) / 1000;
  }

  function handResult(i, fractions, values, handEquity) {
    const h = classes[i];
    const raise = Math.round(fractions.raise * 1e4) / 100;
    const call = Math.min(100 - raise, Math.round(fractions.call * 1e4) / 100);
    return {
      name: h.name, row: h.row, col: h.col, combos: h.combos,
      equity: Math.round(handEquity * 1e4) / 100,
      frequencies: {raise, call, fold: Math.round((100 - raise - call) * 100) / 100},
      ev: {
        raise: values.raise === null ? null : roundEV(values.raise),
        call: values.call === null ? null : roundEV(values.call),
        fold: 0
      }
    };
  }

  function assemble(config, list, actions, modelLabel, description, details = {}) {
    const totals = {raise: 0, call: 0, fold: 0};
    for (const h of list) {
      for (const key of Object.keys(totals)) totals[key] += h.frequencies[key] * h.combos / 1326;
    }
    for (const key of Object.keys(totals)) totals[key] = Math.round(totals[key] * 100) / 100;
    return {
      config, matrix: ranks.map((_, i) => list.slice(i * 13, i * 13 + 13)),
      hands: Object.fromEntries(list.map(h => [h.name, h])), totals,
      actions, modelLabel, description, ...details
    };
  }

  function cashSolution(c) {
    const rfi = c.villain === 'none';
    const inBlind = c.hero === 'BB' || c.hero === 'SB';
    const posted = c.hero === 'BB' ? 1 : c.hero === 'SB' ? .5 : 0;
    const inPosition = c.villain === 'SB' || (!inBlind && positions.indexOf(c.hero) > positions.indexOf(c.villain));
    const multiplier = inPosition ? 3.2 : 4.4;
    const raiseTo = rfi ? c.openSize : Math.min(c.stack, Math.round(c.openSize * multiplier * 2) / 2);
    const facingAllIn = !rfi && c.openSize >= c.stack;
    const actions = facingAllIn ? [] : [{key: 'raise', label: 'Raise', size: raiseTo}];
    if (!rfi) actions.push({key: 'call', label: 'Call', size: c.openSize - posted});
    actions.push({key: 'fold', label: 'Fold', size: null});
    const range = classes.map((_, j) => rfi ? 1 : openWeight(c.villain, j, c.openSize));
    const potAtCall = 2 * c.openSize + (inBlind && c.villain === 'SB' ? 0 : c.hero === 'BB' ? .5 : c.hero === 'SB' ? 1 : 1.5);
    const width = openWidth[c.villain] || .46;
    const cap = c.stack / 100;
    const list = classes.map((h, i) => {
      const eq = rfi ? randomEquity[i] : rangeEquity(i, range);
      if (rfi) {
        const raise = Math.round(openWeight(c.hero, i, c.openSize) * 20) / 20;
        const value = (sizeAdjustedWidth(c.hero, c.openSize) - percentile[i]) * 2.8 + Math.max(0, eq - .68) * 8;
        return handResult(i, {raise, call: 0}, {raise: value, call: null}, eq);
      }
      if (facingAllIn) {
        const value = potAtCall * eq - (c.stack - posted);
        return handResult(i, {raise: 0, call: value > 0 ? 1 : 0}, {raise: null, call: value}, eq);
      }
      const gap = h.low - h.high;
      const connected = h.suited ? Math.max(0, 4 - gap) / 4 : 0;
      const depth = clamp(Math.log2(cap), -2, 2);
      const impliedOdds = depth * ((h.pair && h.high >= 6 ? .025 : 0) + connected * .018);
      const realization = clamp(.69 + (inPosition ? .11 : 0) + (h.suited ? .12 : 0)
        + connected * .055 + (h.pair ? .13 : 0) + (h.low <= 4 ? .065 : 0)
        + (eq - .40) * .38 + impliedOdds, .58, 1.12);
      const callEV = potAtCall * eq * realization - (c.openSize - posted) - .075;
      // Value three-bets expand against late opens; wheel aces and suited
      // connectors add blocker and coverage bluffs at full effective stacks.
      const premium = (eq - (.59 + (.46 - width) * .10)) * 7;
      const wheelAce = h.suited && h.high === 0 && h.low >= 9;
      const bluff = wheelAce ? .36 : connected * .105;
      const strength = premium + (h.pair && h.high < 5 ? .18 : 0) + bluff * Math.min(1, cap);
      let raise = clamp(.44 + strength, 0, 1);
      const squeeze = Math.max(0, c.openSize - 2.5) * .050;
      raise = clamp(raise - squeeze, 0, 1);
      if (wheelAce) raise = Math.max(raise, (.12 + width * .34) * Math.min(1, cap));
      if (connected >= .5 && h.high >= 3 && h.low <= 11) raise = Math.max(raise, (.035 + width * .34) * Math.min(1, cap));
      if (h.suited && h.high === 1 && h.low >= 6) raise = Math.max(raise, width * .27 * Math.min(1, cap));
      if (!h.suited && !h.pair && h.high === 0 && h.low >= 9) raise = Math.max(raise, width * .18 * Math.min(1, cap));
      raise = Math.round(raise * 20) / 20;
      const defend = clamp(.5 + callEV / .36, 0, 1);
      const call = Math.min(1 - raise, Math.round((1 - raise) * defend * 20) / 20);
      const nearAlternative = Math.max(0, callEV);
      const raiseEdge = raise > 0 && raise < 1 ? (raise - .5) * .22
        : (strength + .44 - .50) * Math.min(2.5, raiseTo / 6);
      const raiseEV = nearAlternative + raiseEdge + (h.pair && h.high < 3 ? (3 - h.high) * .65 : 0);
      return handResult(i, {raise, call}, {raise: raiseEV, call: callEV}, eq);
    });
    return assemble(c, list, actions, 'Preflop estimate',
      'Six-max preflop study estimates use sampled showdown equities, position-based opening ranges and a postflop equity realization model. EV is estimated in big blinds from this decision; folding earns zero.');
  }


  // Both solver backends share the identical payoff and private-deal tables.
  // Row i is the SB class, column j is BB. Folding has incremental EV zero.
  function pushFoldModel(input = {}) {
    const config = normalize({...input, model: 'pushfold'});
    const showdown = new Float32Array(n * n);
    for (let k = 0; k < showdown.length; k++) {
      showdown[k] = 1 + config.stack * (1 - 2 * equity[k]);
    }
    return {n, matchups, showdown, iterations: 400};
  }

  function averagePolicies(c, model) {
    const plan = new Float64Array(2 * n).fill(.5);
    const advantage = new Float64Array(2 * n);
    const regret = new Float64Array(2 * n);
    const foldRegret = new Float64Array(2 * n);
    const average = new Float64Array(2 * n);
    const locks = new Float64Array(2 * n).fill(NaN);
    for (const [k, pos] of ['SB', 'BB'].entries()) {
      for (const [i, h] of classes.entries()) {
        const value = c.locks[pos]?.[h.name];
        if (Number.isFinite(value)) plan[k * n + i] = locks[k * n + i] = clamp(value, 0, 1);
      }
    }
    // Precompute the two counterfactual payoff kernels. Their conditionals
    // differ because a dealt class has 4, 6, or 12 possible combinations.
    const sbKernel = new Float64Array(n * n);
    const bbKernel = new Float64Array(n * n);
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        const v = model.showdown[i * n + j];
        sbKernel[i * n + j] = v * matchups[i * n + j];
        bbKernel[j * n + i] = v * matchups[j * n + i];
      }
    }
    for (let t = 1; t <= model.iterations; t++) {
      for (let i = 0; i < n; i++) {
        let sb = 1.5;
        let bb = 0;
        const start = i * n;
        for (let j = 0; j < n; j++) {
          sb -= sbKernel[start + j] * plan[n + j];
          bb += bbKernel[start + j] * plan[j];
        }
        advantage[i] = sb;
        advantage[n + i] = bb;
      }
      for (let k = 0; k < plan.length; k++) {
        const p = plan[k];
        average[k] += t * p;
        if (!Number.isNaN(locks[k])) continue;
        const d = advantage[k];
        regret[k] = Math.max(0, regret[k] + (1 - p) * d);
        foldRegret[k] = Math.max(0, foldRegret[k] - p * d);
        const sum = regret[k] + foldRegret[k];
        plan[k] = sum > 0 ? regret[k] / sum : .5;
      }
    }
    const weight = model.iterations * (model.iterations + 1) / 2;
    for (let k = 0; k < average.length; k++) average[k] /= weight;
    return [average.slice(0, n), average.slice(n)];
  }

  function pushFoldResult(input, sbJam, bbCall) {
    const config = normalize({...input, model: 'pushfold'});
    const sbActing = config.hero === 'SB';
    let sbRegret = 0;
    let bbRegret = 0;
    const list = classes.map((h, i) => {
      const sbEquity = rangeEquity(i, bbCall);
      const bbEquity = rangeEquity(i, sbJam);
      let callChance = 0;
      let jamChance = 0;
      for (let j = 0; j < n; j++) {
        callChance += matchups[i * n + j] * bbCall[j];
        jamChance += matchups[i * n + j] * sbJam[j];
      }
      const sbEV = 1.5 * (1 - callChance) + callChance * (.5 + config.stack * (2 * sbEquity - 1));
      const bbEV = 1 + config.stack * (2 * bbEquity - 1);
      // Per-hand unilateral improvement vs the average opposing strategy.
      // A locked player remains constrained when measuring improvement.
      if (!Number.isFinite(config.locks.SB?.[h.name])) {
        sbRegret += h.combos / 1326 * (Math.max(sbEV, 0) - sbJam[i] * sbEV);
      }
      if (!Number.isFinite(config.locks.BB?.[h.name])) {
        bbRegret += h.combos / 1326 * jamChance * (Math.max(bbEV, 0) - bbCall[i] * bbEV);
      }
      return sbActing
        ? handResult(i, {raise: sbJam[i], call: 0}, {raise: sbEV, call: null}, sbEquity)
        : handResult(i, {raise: 0, call: bbCall[i]}, {raise: null, call: bbEV}, bbEquity);
    });
    return assemble(config, list, [
      sbActing ? {key: 'raise', label: 'Shove', size: config.stack}
        : {key: 'call', label: 'Call', size: config.stack - 1},
      {key: 'fold', label: 'Fold', size: null}
    ], 'Heads-up push/fold CFR+',
    '400 iterations of regret minimization over all 169 hand classes. Heads-up, equal stacks, 0.5/1 blinds, no ante or rake. The small blind shoves or folds. The big blind calls or folds. Showdown payoffs use 12,288 sampled boards per class matchup.',
    {iterations: 400, nashGap: Math.max(0, sbRegret + bbRegret), sampledBoards: 12288});
  }

  const policyCache = new Map();
  function solve(input = {}) {
    const config = normalize(input);
    if (config.model === 'cash') return cashSolution(config);
    const key = JSON.stringify([config.stack, config.locks]);
    if (!policyCache.has(key)) {
      if (policyCache.size >= 24) policyCache.delete(policyCache.keys().next().value);
      policyCache.set(key, averagePolicies(config, pushFoldModel(config)));
    }
    return pushFoldResult(config, ...policyCache.get(key));
  }

  // Input maps use hand-class keys and inclusion weights between zero and one.
  // Equity is weighted by legal disjoint deals, with half credit for ties.
  function compareRanges(first, second) {
    const weights = [first, second].map(range => classes.map(h => numeric(range[h.name] ?? 0, 0, 0, 1)));
    let deals = 0;
    let wins = 0;
    for (let i = 0; i < n; i++) {
      const combos = weights[0][i] * classes[i].combos;
      if (!combos) continue;
      for (let j = 0; j < n; j++) {
        const weight = combos * matchups[i * n + j] * 1225 * weights[1][j];
        deals += weight;
        wins += weight * equity[i * n + j];
      }
    }
    return {deals, equity: deals ? [100 * wins / deals, 100 * (1 - wins / deals)] : [null, null]};
  }

  // solve(config) returns a 13x13 matrix, a map by notation, combo-weighted
  // whole-range totals, action labels/sizes and model metadata. Frequencies
  // and equities are percentages. Null EV means an action is unavailable.
  // Optional push/fold locks use probabilities, e.g. {BB: {AKs: .75}}.
  function matchupStats() {
    return {n, names: classes.map(h => h.name), matchups, equity, ties};
  }
  globalThis.RangeEngine = {solve, ranks, DEFAULT_CONFIG, pushFoldModel, pushFoldResult, compareRanges, matchupStats};
})();
